-- semantic-crosscheck data-rules: the statements of this run, in order (generated from the rule file).
-- Every value is a bound parameter (:pN, :limit): this file holds identifiers and SQL grammar only, never a
-- configured constant, an example value or a row value. For review only: change the rule file and rerun
-- `sxc.py data-rules` instead of running these statements.

-- gate encoding
SHOW server_encoding;

-- rule grams_in_count_unit (text_quantity)
SELECT * FROM (SELECT t."parent_id", t."child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p1 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p2 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p3 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" IN (CAST(:p4 AS text), CAST(:p5 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p6 AS numeric) * x.numerator GROUP BY t."parent_id", t."child_id", t."qty_per", x.numerator, x.divisor) r LIMIT CAST(:limit AS bigint);

-- example grams_in_count_unit[0]
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS text)), (CAST(:p4 AS text), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS text)), (CAST(:p10 AS text), CAST(:p11 AS numeric(18,6)), CAST(:p12 AS text))), "sxc_ex_part"("part_id", "name", "unit") AS (VALUES (CAST(:p13 AS text), CAST(:p14 AS text), CAST(:p15 AS text)), (CAST(:p16 AS text), CAST(:p17 AS text), CAST(:p18 AS text)), (CAST(:p19 AS text), CAST(:p20 AS text), CAST(:p21 AS text)), (CAST(:p22 AS text), CAST(:p23 AS text), CAST(:p24 AS text))) SELECT * FROM (SELECT t."parent_id", t."child_id", t."qty_per", x.numerator AS "numerator", x.divisor AS "divisor", count(*) AS "n" FROM "sxc_ex_bom_line" t JOIN "sxc_ex_part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p25 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p26 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p27 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" IN (CAST(:p28 AS text), CAST(:p29 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p30 AS numeric) * x.numerator GROUP BY t."parent_id", t."child_id", t."qty_per", x.numerator, x.divisor) r;
